		"Login history cleared." => "Historial de login esborrat.",
		"Your administrator requires you to change your password. Update it on your profile page below." => "L'administrador requereix que canviïs la contrasenya. Actualitza-la a la pàgina de perfil.",
		"Defined in TSO flags file" => "Definida al fitxer de flags TSO",
