		"WordPress runtime default" => "Valor per defecte del WordPress",
		"Effective value (filter or core)" => "Valor efectiu (filtre o core)",
		"PHP ini / WordPress fallback" => "PHP ini / fallback WordPress",
		"WordPress default when undefined" => "Valor per defecte del WordPress quan no està definida",
		"Enables WordPress debug mode." => "Activa el mode debug del WordPress.",
		"Writes debug messages to debug.log." => "Escriu missatges de debug a debug.log.",
