		"Rate limit by IP" => "Límit de freqüència per IP",
		"Block disposable email domains" => "Bloquejar dominis de correu temporals",
		"Block duplicate comments" => "Bloquejar comentaris duplicats",
		"Block Cyrillic characters" => "Bloquejar caràcters ciríl·lics",
